        return dict(source_commit=pin,archive_sha256=sha(archive),sources=identities,harness_sha256=sha(HARNESS.encode()),candidate_sha256=sha((tmp/'candidate').read_bytes()),records=count,typed_projection_digest=digest,all_archived_sources_checked_before_and_after=True,exported_archive_unchanged=True,cargo_tests=True,clippy_strict_all_targets=True,actual_truncation_cuts="tracked structural/count/version/scalar boundaries and first interior bytes, recursively restricted to first/last repeated rows; no middle repeated rows",small_source_carrier_every_truncation=True,large_source_carrier_bounded_edge_cuts=True,independent_actual_aggregate_items=True,exact_byte_item_caps=True,one_short_byte_item_caps=True,strict_trailing=True,prefix_tail=True)

